import{_ as t,o as a,c as s,ag as i}from"./chunks/framework.DQQHyi2x.js";const u=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md"}'),o={name:"guide/installation.md"};function n(r,e,d,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Albiex Synth City must run in the same environment where your agent CLIs and credentials are installed. Docker is not supported because containers cannot see host-installed CLIs, host tmux sessions, native agent credentials, or your real repository environment.</p><p>Synth City includes the Overview, Work, Repositories and Harnesses pages (added in 3.0.0). Older packaged releases can show the earlier configuration home page. The installation prerequisites still apply.</p><h2 id="native-installation" tabindex="-1">Native Installation <a class="header-anchor" href="#native-installation" aria-label="Permalink to &quot;Native Installation&quot;">​</a></h2><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><ul><li><strong>Python 3.11+</strong></li><li><strong>Node.js 22.12+</strong></li><li>At least one supported local agent CLI installed on the same host: <ul><li>Claude Code</li><li>Codex CLI</li><li>GitHub Copilot CLI</li><li>OpenCode CLI 2 or later</li><li>Pi</li></ul></li></ul><p>Synth City requires OpenCode 2 or later. It reads the version from <code>opencode --version</code> (for example <code>opencode v2.0.29</code> or <code>2.0.29</code>). With OpenCode 1, or a version it cannot read, the OpenCode harness shows a blocked configuration with the reason &quot;OpenCode 2 or later is required&quot;, and OpenCode team members cannot launch.</p><p>Pi has additional requirements:</p><ul><li>Pi 0.87.1</li><li>Node.js 22.19.0 or later</li><li>The dependencies of the repository-local Agent Mail extension in <code>integrations/pi-agent-mail</code>, prepared before you launch Pi from Synth City</li></ul><p>Agent Mail has no Pi install action. Its <strong>Pi Agent Mail</strong> card on the Install tab only checks whether the extension is ready.</p><h3 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><ol><li>Clone the repository:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/albiexai/synth-city.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> synth-city</span></span></code></pre></div><ol start="2"><li>Run the install script:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/install.sh</span></span></code></pre></div><p>This script:</p><ul><li>Creates a Python virtual environment in <code>backend/venv/</code></li><li>Installs Python dependencies from <code>backend/requirements.txt</code></li><li>Installs Node.js dependencies in <code>frontend/</code></li><li>Installs documentation dependencies in <code>docs/</code></li><li>Creates required directories</li></ul><ol start="3"><li>Start Synth City:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/dev.sh</span></span></code></pre></div><p>Synth City starts the backend at <code>http://localhost:8000</code> and the frontend dev server at <code>http://localhost:5173</code>.</p><ol start="4"><li>Verify the installation:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check backend</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv/bin/activate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;import fastapi; print(&#39;Backend OK&#39;)&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check frontend and docs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/build.sh</span></span></code></pre></div><h2 id="upgrade-and-rollback" tabindex="-1">Upgrade and Rollback <a class="header-anchor" href="#upgrade-and-rollback" aria-label="Permalink to &quot;Upgrade and Rollback&quot;">​</a></h2><p>Synth City runs from a clone of the repository. An upgrade changes the source. It keeps your database, your operator and GitHub settings in <code>backend/.env</code>, and your agent configuration files.</p><h3 id="upgrading-from-v3-1-to-v4-0-0" tabindex="-1">Upgrading from v3.1 to v4.0.0 <a class="header-anchor" href="#upgrading-from-v3-1-to-v4-0-0" aria-label="Permalink to &quot;Upgrading from v3.1 to v4.0.0&quot;">​</a></h3><p>Version 4.0.0 is the rename release, and its upgrade renames data and settings as well as the product. Follow <a href="/docs/guide/migration-v4.html">Moving to Albiex Synth City v4.0.0</a> for that upgrade, including its complete backup and restore contract. Do not use the historical procedure below for a v4 upgrade: its filenames predate the rename.</p><h3 id="historical-procedure-v3-0-0-and-earlier" tabindex="-1">Historical procedure (v3.0.0 and earlier) <a class="header-anchor" href="#historical-procedure-v3-0-0-and-earlier" aria-label="Permalink to &quot;Historical procedure (v3.0.0 and earlier)&quot;">​</a></h3><p>The steps below are the upgrade and rollback procedure as written for v3.0.0 and earlier versions, kept for those versions. They use the database filename from before the rename, <code>backend/claude_registry.db</code>. Do not pair them with a v4 checkout.</p><h4 id="upgrade-historical" tabindex="-1">Upgrade (historical) <a class="header-anchor" href="#upgrade-historical" aria-label="Permalink to &quot;Upgrade (historical)&quot;">​</a></h4><ol><li>Stop the application.</li><li>Copy the database while it is stopped. The database uses SQLite WAL mode, so committed data can be in the <code>-wal</code> file. Use the SQLite backup command and keep the copy outside the repository:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sqlite3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend/claude_registry.db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;.backup &#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/claude_registry.db.before-3.0.0&#39;&quot;</span></span></code></pre></div><p>Without <code>sqlite3</code>, copy <code>claude_registry.db</code>, <code>claude_registry.db-wal</code> and <code>claude_registry.db-shm</code> together. If <code>DATABASE_URL</code> in <code>backend/.env</code> sets another database path, back up that database.</p><ol start="3"><li>Copy <code>backend/.env</code> if you have one. Also create a Backup in the Backup page if you plan to edit agent configuration.</li><li>Update the source and install the dependencies:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tags</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v3.0.0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/install.sh</span></span></code></pre></div><ol start="5"><li>Start the application with <code>./scripts/dev.sh</code>.</li></ol><p>Do not delete the database. At startup, the application adds the listed missing columns and indexes in place and records one-time data migrations. The first start after an upgrade also installs one audit coverage marker. See <a href="/docs/guide/factory-audit-and-metrics.html">Factory audit and metrics</a>.</p><h4 id="rollback-historical" tabindex="-1">Rollback (historical) <a class="header-anchor" href="#rollback-historical" aria-label="Permalink to &quot;Rollback (historical)&quot;">​</a></h4><p>The startup steps do not support downgrade. To roll back, restore the copy you made before the upgrade:</p><ol><li>Stop the application.</li><li>Check out the earlier version. For example, <code>git checkout v2.0.1</code>, then run <code>./scripts/install.sh</code>.</li><li>Remove <code>backend/claude_registry.db-wal</code> and <code>backend/claude_registry.db-shm</code>. A stale file from 3.0.0 can damage the restored database. Then replace <code>backend/claude_registry.db</code> with your copy, for example <code>~/claude_registry.db.before-3.0.0</code>.</li><li>Keep <code>backend/.env</code> unchanged. Start the application.</li></ol><p>Records written after the upgrade are not in the copy. They are lost when you restore it. Rollback does not change your agent configuration files. Use the Backup page to restore those files.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>The dashboard and native pages start with the code defaults in <code>backend/app/config.py</code>. Settings can also come from environment variables or <code>backend/.env</code>. Factory polling (<code>github_token</code>) and operator-protected actions (<code>operator_token</code>) need host settings; see <a href="/docs/autonomy.html">Autonomous GitHub dispatch</a>. The SQLite database is created automatically on first run at <code>backend/synth_city.db</code>.</p><h2 id="remote-use" tabindex="-1">Remote Use <a class="header-anchor" href="#remote-use" aria-label="Permalink to &quot;Remote Use&quot;">​</a></h2><p>For remote access, install and run Synth City natively on the remote host where the agents, credentials, repositories, and tmux sessions exist. Then connect from your browser over a trusted tunnel or network route.</p><h2 id="separate-controller-and-agent-users" tabindex="-1">Separate controller and agent users <a class="header-anchor" href="#separate-controller-and-agent-users" aria-label="Permalink to &quot;Separate controller and agent users&quot;">​</a></h2><p>If the controller and the agents run as different operating-system users, the operator must set up one <code>sudoers</code> rule for the cross-user terminal attach: turn <code>use_pty</code> off for the agent <code>tmux</code> command only. Synth City does not change <code>sudoers</code>. See <a href="/docs/features/agent-bridge.html#what-you-must-set-up-a-command-scoped-use-pty">What you must set up: a command-scoped <code>!use_pty</code></a> and, for the rest of this layout, <a href="/docs/features/agent-teams.html#deployment-with-separate-controller-and-agent-users">Deployment with separate controller and agent users</a>.</p><h2 id="what-gets-read" tabindex="-1">What Gets Read <a class="header-anchor" href="#what-gets-read" aria-label="Permalink to &quot;What Gets Read&quot;">​</a></h2><p>Synth City reads these Claude Code configuration files:</p><table tabindex="0"><thead><tr><th>File/Directory</th><th>Scope</th><th>Description</th></tr></thead><tbody><tr><td><code>~/.claude.json</code></td><td>User</td><td>OAuth, caches, MCP servers</td></tr><tr><td><code>~/.claude/settings.json</code></td><td>User</td><td>User settings, permissions</td></tr><tr><td><code>~/.claude/settings.local.json</code></td><td>User</td><td>Local overrides</td></tr><tr><td><code>~/.claude/commands/</code></td><td>User</td><td>User slash commands</td></tr><tr><td><code>~/.claude/agents/</code></td><td>User</td><td>User agents</td></tr><tr><td><code>~/.claude/skills/</code></td><td>User</td><td>User skills</td></tr><tr><td><code>~/.claude/projects/</code></td><td>User</td><td>Session transcripts &amp; usage</td></tr><tr><td><code>.claude/settings.json</code></td><td>Project</td><td>Project settings</td></tr><tr><td><code>.claude/commands/</code></td><td>Project</td><td>Project commands</td></tr><tr><td><code>.mcp.json</code></td><td>Project</td><td>Project MCP servers</td></tr><tr><td><code>CLAUDE.md</code></td><td>Project</td><td>Project instructions</td></tr></tbody></table>`,49)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
